// This file is generated by AI.

// 主题: 解析用户偏好, 并写到 `<html data-theme>` 上 —— `styles.css` 靠这个属性切换全部
// CSS 变量 (`:root` 是浅色, `[data-theme='dark']` 覆盖成深色)。
//
// **主题的唯一写入者是 `routes/+layout.svelte`**: 它先在模块作用域写一次 (要早于首帧), 再用
// 一个 `$effect` 同时维护 `data-theme` / `store.theme` / Monaco 主题。这里刻意不提供"订阅系统
// 主题"的第二个入口 —— 两个写入者会让界面、标题栏图标与 Monaco 各说各话。

import type { ThemePreference } from './settings';

export type ResolvedTheme = 'light' | 'dark';

/** 把偏好 (含 `system`) 解析成实际主题。 */
export function resolveTheme(preference: ThemePreference): ResolvedTheme {
  if (preference !== 'system') return preference;
  return window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
}

/** 把主题写到根元素上。**首帧之前**调用, 否则会看到一帧浅色再跳成深色。 */
export function applyTheme(theme: ResolvedTheme): void {
  document.documentElement.setAttribute('data-theme', theme);
}
